356→func sessionStateBackfillTokenUsage(ctx context.Context, ag agent.Agent, agentType types.AgentType, transcript []byte, checkpointUsage *agent.TokenUsage) *agent.TokenUsage {
357→	if agentType == agent.AgentTypeCopilotCLI && len(transcript) > 0 {
358→		fullSessionUsage := agent.CalculateTokenUsage(ctx, ag, transcript, 0, "")
359→		if hasTokenUsageData(fullSessionUsage) {
360→			return fullSessionUsage
361→		}
362→		logging.Debug(ctx, "copilot-cli: full-session token read produced no data, falling back to checkpoint usage")
363→	}
