365→	if agentType == agent.AgentTypeCopilotCLI && hasTokenUsageData(checkpointUsage) {
366→		return checkpointUsage
367→	}
368→
369→	if checkpointUsage != nil && checkpointUsage.InputTokens > 0 {
370→		return checkpointUsage
371→	}
