379→	shadowTree            *object.Tree        // Shadow branch tree (already resolved by PostCommit)
380→	parentTree            *object.Tree        // Parent commit tree (nil for initial commits, for consistent non-agent line counting)
381→	repoDir               string              // Repository worktree path for git CLI commands
382→	parentCommitHash      string              // HEAD's first parent hash (preferred diff base for non-agent files)
383→	attributionBaseCommit string              // Base commit hash for non-agent file detection (empty = fall back to go-git tree walk)
384→	headCommitHash        string              // HEAD commit hash for non-agent file detection (empty = fall back to go-git tree walk)
