388→func calculateSessionAttributions(ctx context.Context, repo *git.Repository, shadowRef *plumbing.Reference, sessionData *ExtractedSessionData, state *SessionState, opts ...attributionOpts) *cpkg.InitialAttribution {
389→	// Calculate initial attribution using accumulated prompt attribution data.
390→	// This uses user edits captured at each prompt start (before agent works),
391→	// plus any user edits after the final checkpoint (shadow → head).
392→	//
393→	// When shadowRef is nil (agent committed mid-turn before SaveStep),
394→	// HEAD is used as the shadow tree. This is correct because the agent's
395→	// commit IS HEAD — there are no user edits between agent work and commit.
396→	logCtx := logging.WithComponent(ctx, "attribution")
397→
398→	var o attributionOpts
399→	if len(opts) > 0 {

400→		o = opts[0]
401→	}
402→
403→	headTree := o.headTree
404→	if headTree == nil {
405→		headRef, headErr := repo.Head()
406→		if headErr != nil {
407→			logging.Debug(logCtx, "attribution skipped: failed to get HEAD",
408→				slog.String("error", headErr.Error()))
409→			return nil
410→		}
411→
412→		headCommit, commitErr := repo.CommitObject(headRef.Hash())
413→		if commitErr != nil {
414→			logging.Debug(logCtx, "attribution skipped: failed to get HEAD commit",
415→				slog.String("error", commitErr.Error()))
416→			return nil
417→		}
418→
419→		var treeErr error
420→		headTree, treeErr = headCommit.Tree()
421→		if treeErr != nil {
422→			logging.Debug(logCtx, "attribution skipped: failed to get HEAD tree",
423→				slog.String("error", treeErr.Error()))
424→			return nil
425→		}
426→	}
427→
428→	// Get shadow tree: from pre-resolved cache, shadow branch, or HEAD (agent committed directly).
429→	shadowTree := o.shadowTree
430→	if shadowTree == nil {
431→		if shadowRef != nil {
432→			shadowCommit, shadowErr := repo.CommitObject(shadowRef.Hash())
433→			if shadowErr != nil {
434→				logging.Debug(logCtx, "attribution skipped: failed to get shadow commit",
435→					slog.String("error", shadowErr.Error()),
436→					slog.String("shadow_ref", shadowRef.Hash().String()))
437→				return nil
438→			}
439→			var shadowTreeErr error
440→			shadowTree, shadowTreeErr = shadowCommit.Tree()
441→			if shadowTreeErr != nil {
442→				logging.Debug(logCtx, "attribution skipped: failed to get shadow tree",
443→					slog.String("error", shadowTreeErr.Error()))
444→				return nil
445→			}
446→		} else {
447→			// No shadow branch: agent committed mid-turn. Use HEAD as shadow
448→			// because the agent's work is the commit itself.
449→			logging.Debug(logCtx, "attribution: using HEAD as shadow (no shadow branch)")
450→			shadowTree = headTree
451→		}
452→	}
453→
454→	// Get base tree (state before session started)
455→	var baseTree *object.Tree
456→	attrBase := state.AttributionBaseCommit
457→	if attrBase == "" {
458→		attrBase = state.BaseCommit // backward compat
459→	}
460→	if baseCommit, baseErr := repo.CommitObject(plumbing.NewHash(attrBase)); baseErr == nil {
461→		if tree, baseTErr := baseCommit.Tree(); baseTErr == nil {
462→			baseTree = tree
463→		} else {
464→			logging.Debug(logCtx, "attribution: base tree unavailable",
465→				slog.String("error", baseTErr.Error()))
466→		}
467→	} else {
468→		logging.Debug(logCtx, "attribution: base commit unavailable",
469→			slog.String("error", baseErr.Error()),
470→			slog.String("attribution_base", attrBase))
471→	}
472→
473→	// Include PendingPromptAttribution if it was never moved to PromptAttributions.
474→	// This happens when an agent commits mid-turn without calling SaveStep (e.g., Codex).
475→	// PendingPromptAttribution is set during UserPromptSubmit but only moved to
476→	// PromptAttributions during SaveStep. Without this, mid-turn commits have no PA
477→	// data and pre-session worktree dirt cannot be identified for baseline exclusion.
478→	promptAttrs := state.PromptAttributions
479→	if state.PendingPromptAttribution != nil {
480→		promptAttrs = append(promptAttrs, *state.PendingPromptAttribution)
481→	}
482→
483→	// Log accumulated prompt attributions for debugging
484→	var totalUserAdded, totalUserRemoved int
485→	for i, pa := range promptAttrs {
486→		totalUserAdded += pa.UserLinesAdded
487→		totalUserRemoved += pa.UserLinesRemoved
488→		logging.Debug(logCtx, "prompt attribution data",
489→			slog.Int("checkpoint", pa.CheckpointNumber),
490→			slog.Int("user_added", pa.UserLinesAdded),
491→			slog.Int("user_removed", pa.UserLinesRemoved),
492→			slog.Int("agent_added", pa.AgentLinesAdded),
493→			slog.Int("agent_removed", pa.AgentLinesRemoved),
494→			slog.Int("index", i))
495→	}
496→
497→	attribution := CalculateAttributionWithAccumulated(ctx, AttributionParams{
498→		BaseTree:              baseTree,
499→		ShadowTree:            shadowTree,
500→		HeadTree:              headTree,
501→		ParentTree:            o.parentTree,
502→		FilesTouched:          sessionData.FilesTouched,
503→		PromptAttributions:    promptAttrs,
504→		RepoDir:               o.repoDir,
505→		ParentCommitHash:      o.parentCommitHash,
506→		AttributionBaseCommit: attrBase,
507→		HeadCommitHash:        o.headCommitHash,
508→		AllAgentFiles:         o.allAgentFiles,
509→	})
510→
511→	if attribution != nil {
512→		logging.Info(logCtx, "attribution calculated",
513→			slog.Int("agent_lines", attribution.AgentLines),
514→			slog.Int("human_added", attribution.HumanAdded),
515→			slog.Int("human_modified", attribution.HumanModified),
516→			slog.Int("human_removed", attribution.HumanRemoved),
517→			slog.Int("total_committed", attribution.TotalCommitted),
518→			slog.Float64("agent_percentage", attribution.AgentPercentage),
519→			slog.Int("accumulated_user_added", totalUserAdded),
520→			slog.Int("accumulated_user_removed", totalUserRemoved),
521→			slog.Int("files_touched", len(sessionData.FilesTouched)))
522→	}
523→
524→	return attribution
525→}
