527→// committedFilesExcludingMetadata returns committed files with CLI metadata paths filtered out.
528→// `.entire/` files are created by `entire enable`, not by the agent, and should not be
529→// attributed as agent work when used as a fallback for sessions with no FilesTouched.
530→func committedFilesExcludingMetadata(committedFiles map[string]struct{}) []string {
531→	result := make([]string, 0, len(committedFiles))
532→	for f := range committedFiles {
533→		if strings.HasPrefix(f, ".entire/") || strings.HasPrefix(f, paths.EntireMetadataDir+"/") {
534→			continue
535→		}
536→		result = append(result, f)
537→	}
538→	return result
