541→// extractSessionData extracts session data from the shadow branch.
542→// filesTouched is the list of files tracked during the session (from SessionState.FilesTouched).
543→// agentType identifies the agent (e.g., "Gemini CLI", "Claude Code") to determine transcript format.
544→// liveTranscriptPath, when non-empty and readable, is preferred over the shadow branch copy.
545→// This handles the case where SaveStep was skipped (no code changes) but the transcript
546→// continued growing — the shadow branch copy would be stale.
547→// checkpointTranscriptStart is the line offset (Claude) or message index (Gemini) where the current checkpoint began.
548→func (s *ManualCommitStrategy) extractSessionData(ctx context.Context, repo *git.Repository, shadowRef plumbing.Hash, sessionID string, filesTouched []string, agentType types.AgentType, liveTranscriptPath string, checkpointTranscriptStart int, isActive bool) (*ExtractedSessionData, error) {
549→	ag, _ := agent.GetByAgentType(agentType) //nolint:errcheck // ag may be nil for unknown agent types; callers use type assertions so nil is safe
550→	commit, err := repo.CommitObject(shadowRef)
551→	if err != nil {
552→		return nil, fmt.Errorf("failed to get commit object: %w", err)
553→	}
554→
555→	tree, err := commit.Tree()
556→	if err != nil {
557→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
558→	}
559→
560→	data := &ExtractedSessionData{}
561→	// sessionID is already an "entire session ID" (with date prefix)
562→	metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
563→
564→	// Extract transcript — prefer the live file when available, fall back to shadow branch.
565→	// The shadow branch copy may be stale if the last turn ended without code changes
566→	// (SaveStep is only called when there are file modifications).
567→	var fullTranscript string
568→	if liveTranscriptPath != "" {
569→		// Ensure transcript file exists (OpenCode creates it lazily via `opencode export`).
570→		// Only wait for flush when the session is active — for idle/ended sessions the
571→		// transcript is already fully flushed (the Stop hook completed the flush).
572→		if isActive {
573→			prepareTranscriptIfNeeded(ctx, ag, liveTranscriptPath)
574→		}
575→		if liveData, readErr := os.ReadFile(liveTranscriptPath); readErr == nil && len(liveData) > 0 { //nolint:gosec // path from session state
576→			fullTranscript = string(liveData)
577→		}
578→	}
579→	if fullTranscript == "" {
580→		// Fall back to shadow branch copy
581→		if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
582→			if content, contentErr := file.Contents(); contentErr == nil {
583→				fullTranscript = content
584→			}
585→		} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
586→			if content, contentErr := file.Contents(); contentErr == nil {
587→				fullTranscript = content
588→			}
589→		}
590→	}
591→
592→	// Process transcript based on agent type
593→	if fullTranscript != "" {
594→		data.Transcript = []byte(fullTranscript)
595→		data.FullTranscriptLines = countTranscriptItems(agentType, fullTranscript)
596→		// Read prompts from shadow branch tree (source of truth after SaveStep)
597→		if file, fileErr := tree.File(metadataDir + "/" + paths.PromptFileName); fileErr == nil {
598→			if content, contentErr := file.Contents(); contentErr == nil && content != "" {
599→				data.Prompts = splitPromptContent(content)

600→			}
601→		}
602→		// Filesystem fallback (written at turn start, covers mid-turn commits)
603→		if len(data.Prompts) == 0 {
604→			data.Prompts = readPromptsFromFilesystem(ctx, sessionID)
605→		}
606→	}
607→
608→	// Use tracked files from session state (not all files in tree)
609→	data.FilesTouched = filesTouched
610→
611→	// Calculate token usage from the extracted transcript portion
612→	if len(data.Transcript) > 0 {
613→		data.TokenUsage = agent.CalculateTokenUsage(ctx, ag, data.Transcript, checkpointTranscriptStart, "") //TODO: why do we not use here subagents dir?
614→	}
615→
616→	return data, nil
617→}
