619→// extractSessionDataFromLiveTranscript extracts session data directly from the live transcript file.
620→// This is used for mid-session commits where no shadow branch exists yet.
621→func (s *ManualCommitStrategy) extractSessionDataFromLiveTranscript(ctx context.Context, state *SessionState) (*ExtractedSessionData, error) {
622→	data := &ExtractedSessionData{}
623→
624→	ag, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; callers use type assertions so nil is safe
625→
626→	// Resolve the transcript path (handles agents that relocate mid-session).
627→	transcriptPath, resolveErr := resolveTranscriptPath(state)
628→	if resolveErr != nil {
629→		return nil, resolveErr
630→	}
631→
632→	liveData, err := os.ReadFile(transcriptPath) //nolint:gosec // path validated by resolveTranscriptPath
633→	if err != nil {
634→		return nil, fmt.Errorf("failed to read live transcript: %w", err)
635→	}
636→
637→	if len(liveData) == 0 {
638→		return nil, errors.New("live transcript is empty")
639→	}
640→
641→	fullTranscript := string(liveData)
642→	data.Transcript = liveData
643→	data.FullTranscriptLines = countTranscriptItems(state.AgentType, fullTranscript)
644→	data.Prompts = readPromptsFromFilesystem(ctx, state.SessionID)
645→
646→	// Resolve files touched: prefers hook-populated state, falls back to transcript extraction
647→	data.FilesTouched = s.resolveFilesTouched(ctx, state)
648→
649→	// Calculate token usage from the extracted transcript portion
650→	if len(data.Transcript) > 0 {
651→		data.TokenUsage = agent.CalculateTokenUsage(ctx, ag, data.Transcript, state.CheckpointTranscriptStart, "") //TODO: why do we not use here subagents dir?
652→	}
