657→// countTranscriptItems counts lines (JSONL) or messages (JSON) in a transcript.
658→// For Claude Code and JSONL-based agents, this counts lines.
659→// For Gemini CLI, OpenCode, and JSON-based agents, this counts messages.
660→// Returns 0 if the content is empty or malformed.
661→func countTranscriptItems(agentType types.AgentType, content string) int {
662→	if content == "" {
663→		return 0
664→	}
665→
666→	// OpenCode uses export JSON format with {"info": {...}, "messages": [...]}
667→	if agentType == agent.AgentTypeOpenCode {
668→		session, err := opencode.ParseExportSession([]byte(content))
669→		if err == nil && session != nil {
670→			return len(session.Messages)
671→		}
672→		return 0
673→	}
674→
675→	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
676→	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
677→		transcript, err := geminicli.ParseTranscript([]byte(content))
678→		if err == nil && transcript != nil && len(transcript.Messages) > 0 {
679→			return len(transcript.Messages)
680→		}
681→		// If agentType is explicitly Gemini but parsing failed, return 0
682→		if agentType == agent.AgentTypeGemini {
683→			return 0
684→		}
685→		// Otherwise fall through to JSONL parsing for Unknown type
686→	}
687→
688→	// Claude Code and other JSONL-based agents
689→	allLines := strings.Split(content, "\n")
690→	// Trim trailing empty lines (from final \n in JSONL)
691→	for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
692→		allLines = allLines[:len(allLines)-1]
693→	}
694→	return len(allLines)
695→}
