697→// extractUserPrompts extracts all user prompts from transcript content.
698→// Returns prompts with IDE context tags stripped (e.g., <ide_opened_file>).
699→func extractUserPrompts(agentType types.AgentType, content string) []string {
700→	if content == "" {
701→		return nil
702→	}
703→
704→	// Droid has its own envelope format — use its parser to normalize first
705→	if agentType == agent.AgentTypeFactoryAIDroid {
706→		lines, _, err := factoryaidroid.ParseDroidTranscriptFromBytes([]byte(content), 0)
707→		if err != nil {
708→			return nil
709→		}
710→		var prompts []string
711→		for _, line := range lines {
712→			if line.Type != transcript.TypeUser {
713→				continue
714→			}
715→			if text := transcript.ExtractUserContent(line.Message); text != "" {
716→				if stripped := textutil.StripIDEContextTags(text); stripped != "" {
717→					prompts = append(prompts, stripped)
718→				}
719→			}
720→		}
721→		return prompts
722→	}
723→
724→	// OpenCode uses JSONL with a different per-line schema than Claude Code
725→	if agentType == agent.AgentTypeOpenCode {
726→		prompts, err := opencode.ExtractAllUserPrompts([]byte(content))
727→		if err == nil && len(prompts) > 0 {
728→			cleaned := make([]string, 0, len(prompts))
729→			for _, prompt := range prompts {
730→				if stripped := textutil.StripIDEContextTags(prompt); stripped != "" {
731→					cleaned = append(cleaned, stripped)
732→				}
733→			}
