151→// Bytes is a convenience wrapper around String for []byte content.
152→func Bytes(b []byte) []byte {
153→	s := string(b)
154→	redacted := String(s)
155→	if redacted == s {
156→		return b
157→	}
158→	return []byte(redacted)
159→}
