161→// JSONLBytes is a convenience wrapper around JSONLContent for []byte content.
162→func JSONLBytes(b []byte) ([]byte, error) {
163→	s := string(b)
164→	redacted, err := JSONLContent(s)
165→	if err != nil {
166→		return nil, err
167→	}
168→	if redacted == s {
169→		return b, nil
170→	}
171→	return []byte(redacted), nil
172→}
173→
174→// JSONLContent parses each line as JSON to determine which string values
175→// need redaction, then performs targeted replacements on the raw JSON bytes.
176→// Lines with no secrets are returned unchanged, preserving original formatting.
177→//
178→// For multi-line JSON content (e.g., pretty-printed single JSON objects like
179→// OpenCode export), the function first attempts to parse the entire content as
180→// a single JSON value. This ensures field-aware redaction (which skips ID fields)
181→// is used instead of falling back to entropy-based detection on raw text lines,
182→// which would corrupt high-entropy identifiers.
183→func JSONLContent(content string) (string, error) {
184→	// Try parsing the entire content as a single JSON value first.
185→	// Uses a streaming decoder to avoid copying the full content into []byte.
186→	// After decoding, attempts a second Decode to confirm EOF — if it succeeds,
187→	// the content is JSONL (multiple values) and we fall through to line-by-line.
188→	trimmed := strings.TrimSpace(content)
189→	if len(trimmed) > 0 {
190→		dec := json.NewDecoder(strings.NewReader(trimmed))
191→		var parsed any
192→		if err := dec.Decode(&parsed); err == nil && isSingleJSONValue(dec) {
193→			// Content is a single JSON value (object/array) — redact field-aware.
194→			result, err := applyJSONReplacements(content, collectJSONLReplacements(parsed))
195→			if err != nil {
196→				return "", err
197→			}
198→			return result, nil
199→		}
200→	}
201→
202→	// Fall back to line-by-line JSONL processing.
203→	lines := strings.Split(content, "\n")
204→	var b strings.Builder
205→	for i, line := range lines {
206→		if i > 0 {
207→			b.WriteByte('\n')
208→		}
209→		lineTrimmed := strings.TrimSpace(line)
210→		if lineTrimmed == "" {
211→			b.WriteString(line)
212→			continue
213→		}
214→		var parsed any
215→		if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
216→			b.WriteString(String(line))
217→			continue
218→		}
219→		result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed))
220→		if err != nil {
221→			return "", err
222→		}
223→		b.WriteString(result)
224→	}
225→	return b.String(), nil
226→}
227→
228→// applyJSONReplacements applies collected (original, redacted) string pairs
229→// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
230→// Returns s unchanged if repls is empty.
231→func applyJSONReplacements(s string, repls [][2]string) (string, error) {
232→	if len(repls) == 0 {
233→		return s, nil
234→	}
235→	for _, r := range repls {
236→		origJSON, err := jsonEncodeString(r[0])
237→		if err != nil {
238→			return "", err
239→		}
240→		replJSON, err := jsonEncodeString(r[1])
241→		if err != nil {
242→			return "", err
243→		}
244→		s = strings.ReplaceAll(s, origJSON, replJSON)
245→	}
246→	return s, nil
247→}
248→
249→// isSingleJSONValue returns true if the decoder has reached EOF (no more
250→// top-level values). This distinguishes a single JSON value (e.g., pretty-printed
251→// object) from JSONL (multiple concatenated values). We attempt a second Decode
252→// and require io.EOF rather than relying on dec.More(), which is documented for
253→// use inside arrays/objects and not for top-level value boundaries.
254→func isSingleJSONValue(dec *json.Decoder) bool {
255→	var discard json.RawMessage
256→	return dec.Decode(&discard) == io.EOF
257→}
258→
259→// collectJSONLReplacements walks a parsed JSON value and collects unique
260→// (original, redacted) string pairs for values that need redaction.
261→func collectJSONLReplacements(v any) [][2]string {
262→	seen := make(map[string]bool)
263→	var repls [][2]string
264→	var walk func(v any)
265→	walk = func(v any) {
266→		switch val := v.(type) {
267→		case map[string]any:
268→			if shouldSkipJSONLObject(val) {
269→				return
270→			}
271→			for k, child := range val {
272→				if shouldSkipJSONLField(k) {
273→					continue
274→				}
275→				walk(child)
276→			}
277→		case []any:
278→			for _, child := range val {
279→				walk(child)
280→			}
281→		case string:
282→			redacted := String(val)
283→			if redacted != val && !seen[val] {
284→				seen[val] = true
285→				repls = append(repls, [2]string{val, redacted})
286→			}
287→		}
288→	}
289→	walk(v)
290→	return repls
291→}
292→
293→// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
294→// Skips "signature" (exact), ID fields (ending in "id"/"ids"), and common path/directory fields.
295→func shouldSkipJSONLField(key string) bool {
296→	if key == "signature" {
297→		return true
298→	}
299→	lower := strings.ToLower(key)
300→
301→	// Skip ID fields
302→	if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
303→		return true
304→	}
305→
306→	// Skip common path and directory fields from agent transcripts.
307→	// These appear frequently in tool calls and are structural, not secrets.
308→	switch lower {
309→	case "filepath", "file_path", "cwd", "root", "directory", "dir", "path":
310→		return true
311→	}
312→
313→	return false
314→}
315→
316→// shouldSkipJSONLObject returns true if the object has "type":"image" or "type":"image_url".
317→func shouldSkipJSONLObject(obj map[string]any) bool {
318→	t, ok := obj["type"].(string)
319→	return ok && (strings.HasPrefix(t, "image") || t == "base64")
320→}
321→
322→func shannonEntropy(s string) float64 {
323→	if len(s) == 0 {
324→		return 0
325→	}
326→	freq := make(map[byte]int)
327→	for i := range len(s) {
328→		freq[s[i]]++
329→	}
330→	length := float64(len(s))
331→	var entropy float64
332→	for _, count := range freq {
333→		p := float64(count) / length
334→		entropy -= p * math.Log2(p)
335→	}
336→	return entropy
337→}
338→
339→// jsonEncodeString returns the JSON encoding of s without HTML escaping.
340→func jsonEncodeString(s string) (string, error) {
341→	var buf bytes.Buffer
342→	enc := json.NewEncoder(&buf)
343→	enc.SetEscapeHTML(false)
344→	if err := enc.Encode(s); err != nil {
345→		return "", fmt.Errorf("json encode string: %w", err)
346→	}
347→	return strings.TrimSuffix(buf.String(), "\n"), nil
348→}
